class Solution {
    private int[][] dirs = {{-1, 0}, {0, 1}, {1, 0}, {0, -1}};
    private Set<String> visited = new HashSet<>();

    private void goBack(Robot robot) {
        robot.turnRight();
        robot.turnRight();
        robot.move();
        robot.turnRight();
        robot.turnRight();
    }

    private void dfs(Robot robot, int r, int c, int d) {
        visited.add(r + "," + c);
        robot.clean();
        for (int i = 0; i < 4; i++) {
            int nd = (d + i) % 4;
            int nr = r + dirs[nd][0];
            int nc = c + dirs[nd][1];
            if (!visited.contains(nr + "," + nc) && robot.move()) {
                dfs(robot, nr, nc, nd);
                goBack(robot);
            }
            robot.turnRight();
        }
    }

    public void cleanRoom(Robot robot) {
        dfs(robot, 0, 0, 0);
    }
}

/**
 * @param {Robot} robot
 * @return {void}
