var cleanRoom = function(robot) {
    const dirs = [[-1, 0], [0, 1], [1, 0], [0, -1]];
    const visited = new Set();

    function goBack() {
        robot.turnRight();
        robot.turnRight();
        robot.move();
        robot.turnRight();
        robot.turnRight();
    }

    function dfs(r, c, d) {
        visited.add(`${r},${c}`);
        robot.clean();
        for (let i = 0; i < 4; i++) {
            const nd = (d + i) % 4;
            const nr = r + dirs[nd][0];
            const nc = c + dirs[nd][1];
            if (!visited.has(`${nr},${nc}`) && robot.move()) {
                dfs(nr, nc, nd);
                goBack();
            }
            robot.turnRight();
        }
    }

    dfs(0, 0, 0);
};
